package com.library.catalogsets;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import java.nio.file.*;
import java.util.*;
import static com.library.catalogattributes.CatalogAttributeSupport.*;
import static org.junit.jupiter.api.Assertions.*;

/** Uses only the explicitly disposable test schema. Creates its own V14 schema and upgrades only to V15, independent of later migrations. */
@EnabledIfEnvironmentVariable(named="MYSQL_TEST_URL",matches=".+")
public class CatalogSetUpgradeTest {
    static String fingerprint(List<Map<String,Object>> rows){List<Map<String,Object>> result=new ArrayList<>();for(var row:rows){Map<String,Object> n=new TreeMap<>();row.forEach((k,v)->n.put(k,v instanceof java.time.temporal.TemporalAccessor?v.toString():v));result.add(n);}return hash(result);}
    @Test void actualV14ToV15PreservesOldColumnsAndNonemptyPublicationHistory()throws Exception{
        String url=System.getenv("MYSQL_TEST_URL"),user=System.getenv().getOrDefault("MYSQL_TEST_USER","root"),password=System.getenv("MYSQL_TEST_PASSWORD");if(!url.matches("jdbc:mysql://[^/]+/library_repair_tests(?:\\?.*)?"))throw new IllegalStateException("Disposable schema only");String schema="library_repair_b34_upgrade_"+UUID.randomUUID().toString().replace("-", "");JdbcTemplate owner=new JdbcTemplate(new DriverManagerDataSource(url,user,password));owner.execute("CREATE DATABASE `"+schema+"` CHARACTER SET utf8mb4");try{url=url.replace("/library_repair_tests", "/"+schema);JdbcTemplate j=new JdbcTemplate(new DriverManagerDataSource(url,user,password));long tables=j.queryForObject("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE()",Long.class);if(tables==0)Flyway.configure().dataSource(url,user,password).locations("classpath:db/migration").target("14").load().migrate();boolean upgrade=j.queryForObject("SELECT COUNT(*) FROM flyway_schema_history WHERE version='15'",Long.class)==0;
        if(upgrade&&j.queryForObject("SELECT COUNT(*) FROM book WHERE id=893401",Integer.class)==0){j.update("INSERT INTO book(id,isbn,title,publish_date,pages,description,publication_revision,stock_total,stock_available) VALUES (893401,'B34-V14-FROZEN','合成旧书目','2024-02-29',0,?,7,0,0)","V14原简介\n\t📚");j.update("INSERT INTO catalog_publication_request(id,operation_key,actor_id,mode,input_hash,request_json,preview_json,preview_digest,state,created_at,expires_at,receipt_json,committed_at) VALUES (893401,X'423334',893401,'MANUAL',?,'{\"null\":null}','{\"zero\":0}',?,'COMMITTED','2026-01-01','2026-01-02','{\"empty\":\"\"}','2026-01-01')","a".repeat(64),"b".repeat(64));j.update("INSERT INTO catalog_publication_event(book_id,request_id,kind,before_revision,after_revision,changed_fields_json,before_json,after_json,evidence_json,actor_id,occurred_at,reason) VALUES (893401,893401,'MANUAL',6,7,'[\"pages\"]','{\"pages\":null}','{\"pages\":0}','{\"reference\":\"合成旧依据\"}',893401,'2026-01-01','合成旧理由')");}
        var columns=j.queryForList("SELECT table_name,column_name FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name<>'flyway_schema_history' ORDER BY table_name,ordinal_position");Map<String,List<String>> grouped=new TreeMap<>();for(var c:columns)grouped.computeIfAbsent(c.get("TABLE_NAME").toString(),k->new ArrayList<>()).add(c.get("COLUMN_NAME").toString());Map<String,String> before=new TreeMap<>();for(var e:grouped.entrySet())before.put(e.getKey(),fingerprint(j.queryForList("SELECT "+e.getValue().stream().map(c->"`"+c+"`").reduce((a,b)->a+","+b).orElseThrow()+" FROM `"+e.getKey()+"` ORDER BY 1")));var flyway=Flyway.configure().dataSource(url,user,password).locations("classpath:db/migration").target("15").load();assertEquals(upgrade?1:0,flyway.migrate().migrationsExecuted);assertEquals(0,flyway.migrate().migrationsExecuted);for(var e:grouped.entrySet())assertEquals(before.get(e.getKey()),fingerprint(j.queryForList("SELECT "+e.getValue().stream().map(c->"`"+c+"`").reduce((a,b)->a+","+b).orElseThrow()+" FROM `"+e.getKey()+"` ORDER BY 1")),e.getKey());assertEquals(70,j.queryForObject("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE()",Integer.class));if(upgrade){assertEquals(64,grouped.size());assertEquals(0,j.queryForObject("SELECT COUNT(*) FROM book WHERE catalog_set_book_revision<>0",Integer.class));}
        Map<String,Object> ddl=new TreeMap<>();for(String table:List.of("book","catalog_set","catalog_set_member","catalog_set_request","catalog_set_request_book","catalog_set_event"))ddl.put(table,j.queryForMap("SHOW CREATE TABLE "+table).get("Create Table"));String dir=System.getProperty("b34.evidence.dir");if(dir!=null)Files.writeString(Path.of(dir,"actual-ddl-and-upgrade.json"),JSON.writerWithDefaultPrettyPrinter().writeValueAsString(obj("actualUpgrade",upgrade,"oldTables",grouped.size()+1,"oldColumnHashes",before,"ddl",ddl)));System.out.println("B34 actualUpgrade="+upgrade+" oldColumnsPreserved=true newTables=5 guardOnly=true");}finally{owner.execute("DROP DATABASE `"+schema+"`");}
    }
}
